class Solution {
public:
    int minimumTime(vector<int>& jobs, vector<int>& workers) {
        sort(jobs.begin(), jobs.end());
        sort(workers.begin(), workers.end());
        int answer = 0;
        for (int i = 0; i < (int)jobs.size(); ++i)
            answer = max(answer, (jobs[i] + workers[i] - 1) / workers[i]);
        return answer;
    }
};
